        if($objects===[]){$body='<div class="fm2-page-header fm2-page-header--queue"><div><h1>Объекты монтажа</h1><p>Контроль подготовки и открытия монтажных работ</p></div><span class="fm2-result-count">0 объектов</span></div><section class="fm2-list-surface"><div class="fm2-list-toolbar">'.$form.'</div><div class="shlz-empty-state fm2-empty"><strong>Объекты не найдены</strong><p>Измените поисковый запрос или статус.</p><a class="shlz-link" href="/pilot/objects">Сбросить фильтры</a></div></section>';return \FMonitor2\PilotHttp\PilotView::document($user,'Объекты монтажа','Объекты монтажа','',$body);}$html=(new \FMonitor2\PilotHttp\ProductionObjectListRenderer())->render($user,$objects);$html=preg_replace('#<div class="fm2-list-toolbar">.*?</div><div class="fm2-table-wrap">#s','<div class="fm2-list-toolbar">'.$form.'</div><div class="fm2-table-wrap">',$html,1)??throw new RuntimeException();$html=preg_replace('#<span class="shlz-status [^"]* fm2-origin-badge">.*?</span>#s','',$html)??throw new RuntimeException();$html=str_replace('<th>Объект и источник</th>','<th>Объект</th>',$html);if($canSchedule){foreach($objects as$o){if(!in_array($o['status']??'',['В работе','Монтажные работы'],true))continue;$id=(int)$o['id'];$button=RapidPilotInspectionSchedule::queueButton($id,'Объект № '.$id.' · '.$o['address'],$csrf);$pattern='#(<tr[^>]*>.*?href="/pilot/objects/'.$id.'".*?<td data-label="Следующий шаг">.*?</td>)(<td class="fm2-row-action">)#s';$html=preg_replace($pattern,'$1<td class="fm2-inspection-action">'.$button.'</td>$2',$html,1)??$html;}$html=str_replace('</body>',RapidPilotInspectionSchedule::dialog($csrf).'</body>',$html);}$notice=(string)($_GET['inspectionScheduled']??'');if(preg_match('/^\d{4}-\d{2}-\d{2}$/D',$notice)===1){$date=DateTimeImmutable::createFromFormat('!Y-m-d',$notice);if($date)$html=str_replace('<main class="fm2-main">','<main class="fm2-main"><p class="fm2-inspection-notice" role="status">Инспекция запланирована на '.$date->format('d.m.Y').'.</p>',$